/* Local compressed loader. Upstream: https://github.com/lrusso/MAME */
window.MAME_READY=(async function(){const base=new URL('.',document.currentScript.src);const response=await fetch(new URL('MAME-engine.js.gz',base));if(!response.ok)throw new Error('Could not load the local arcade engine ('+response.status+').');if(typeof DecompressionStream==='undefined')throw new Error('Use a current Chrome or Edge browser for arcade games.');const bytes=await response.arrayBuffer();const input=new Uint8Array(bytes);let blob;if(input[0]===31&&input[1]===139){blob=await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).blob();}else{blob=new Blob([bytes]);}const url=URL.createObjectURL(new Blob([blob],{type:'text/javascript'}));try{await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=url;script.onload=resolve;script.onerror=()=>reject(new Error('Could not start the local arcade engine.'));document.head.appendChild(script);});}finally{URL.revokeObjectURL(url);}if(typeof window.embedMAME!=='function')throw new Error('Arcade engine did not initialize.');})();
